#include <stdio.h>

int main(void)
{
    struct Node { int value; struct Node *next; };
    struct Node b = {24, NULL};
    struct Node a = {12, &b};
    struct Node *prev = NULL;
    struct Node *cur = &a;
    while (cur != NULL) {
        struct Node *next = cur->next;
        cur->next = prev;
        prev = cur;
        cur = next;
    }
    printf("%d %d\n", prev->value, prev->next->value);
    return 0;
}

